importScripts('xlsx.min.js','core.js');let books={};onmessage=async({data:d})=>{try{if(d.type==='load'){let b=XLSX.read(d.buffer,{type:'array',bookSheets:true});books[d.key]=d.buffer;postMessage({type:'sheets',key:d.key,names:b.SheetNames})}if(d.type==='parse'){let b=XLSX.read(books[d.key],{type:'array',sheets:[d.sheet],cellDates:false,cellStyles:true}),s=b.Sheets[d.sheet];let range=XLSX.utils.decode_range(s['!ref']||'A1');range.e.c=Math.min(range.e.c,80);range.e.r=Math.min(range.e.r,100000);let rows=XLSX.utils.sheet_to_json(s,{header:1,defval:'',range});postMessage({type:'parsed',key:d.key,result:Engine.parse(rows,d.key,{sheet:d.sheet,colors:Object.fromEntries(rows.map((r,i)=>[i+1,Engine.color(s['A'+(i+1)])]))})})}}catch(e){postMessage({type:'error',key:d.key,message:e.message})}};
